#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    vector<int> values = {100, 5, 100, 20};
    vector<int> compressed = values;
    sort(compressed.begin(), compressed.end());
    compressed.erase(unique(compressed.begin(), compressed.end()), compressed.end());
    for (int& value : values) {
        value = (int)(lower_bound(compressed.begin(), compressed.end(), value) - compressed.begin());
    }
    for (int value : values) cout << value << ' ';
    cout << '\n';
    return 0;
}
